namespace LastChaos_ToolBoxNG.Professions;

public enum FieldKind { Integer,Decimal,Text,Boolean,Item,Npc,Zone,Profile,Parent,Geometry,ArtisanRank,Duration }
public sealed record ProfessionField(string Column,string Label,FieldKind Kind=FieldKind.Integer,string Group="General",string Help="",decimal Min=0,decimal Max=int.MaxValue,decimal Scale=1,int DecimalPlaces=0,bool Identity=false,bool Reserved=false,string ReferenceTable="",string Default="0");
public sealed record ProfessionTable(string Name,string Title,string Help,string[] Keys,ProfessionField[] Fields,string Category="");
public static class ProfessionSchema
{
    static ProfessionField F(string c,string label,int min=0,int max=int.MaxValue,string group="General",FieldKind kind=FieldKind.Integer,string help="",decimal scale=1,int places=0,bool identity=false,bool reserved=false,string reference="",string? initial=null)=>new(c,label,kind,group,help,min,max,scale,places,identity,reserved,reference,initial??min.ToString(System.Globalization.CultureInfo.InvariantCulture));
    static ProfessionField Id()=>F("a_index","Permanent ID",1,identity:true);
    static ProfessionField On()=>F("a_enable","Enabled",0,1,kind:FieldKind.Boolean,initial:"1");
    static ProfessionField Item(string c="a_item_index",string label="Resource item")=>F(c,label,1,kind:FieldKind.Item);
    static ProfessionField Time(string c,string label,int min,int max,string group="Timing",string help="")=>F(c,label,min,max,group,help:help,scale:1000,places:3);
    static ProfessionField Bp(string c,string label,int min,int max,string group="Progression",string help="")=>F(c,label,min,max,group,help:help,scale:100,places:2);
    static ProfessionField Parent(string c,string label,string table)=>F(c,label,1,kind:FieldKind.Parent,reference:table,identity:true);
    static ProfessionField[] Progression(bool passive)=>[
        F("a_skill_cap","Maximum skill",1,65535,"Progression"),Bp("a_min_chance_bp","Minimum skill-up chance (%)",1,10000),F("a_decline_levels","Chance decline levels",1,65535,"Progression",help:"Base chance × decline / (decline + skill − required skill), clamped to the minimum."),
        ..(passive?new[]{Bp("a_yield_per_level_bp","Active yield per level (%)",0,10000),Bp("a_max_yield_bp","Maximum active yield bonus (%)",0,100000),Bp("a_passive_speed_per_level_bp","Passive speed per level (%)",0,10000,"Passive", "Stored but unused by Herbalism."),Bp("a_passive_max_speed_bp","Maximum passive speed bonus (%)",0,10000,"Passive"),Bp("a_passive_skill_rate_bp","Passive skill rate vs active (%)",0,10000,"Passive")}:Array.Empty<ProfessionField>())];
    static ProfessionField[] Loot(string parent,string table)=>[Parent(parent,"Source",table),F("a_slot","Order (zero based)",0,31,identity:true),Item(),F("a_item_count","Quantity",1,1000),F("a_weight","Relative weight",1,1000000,help:"One exclusive outcome. Chance is this weight divided by all enabled weights."),On()];
