    public static ProfessionTable Find(string name) => Tables.FirstOrDefault(t=>t.Name==name)??throw new ArgumentException("Unknown profession content table.",nameof(name));
    public static ProfessionRow NewRow(string table) {var row=new ProfessionRow();foreach(var field in Find(table).Fields)row.Set(field.Column,field.Default);return row;}
}
